Here is the commit message:
fs/ntfs3: Fix transform resident to nonresident for
 compressed files
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Сorrected calculation of required space len (in clusters)
for attribute data storage in case of compression.

Fixes: be71b5cba2e64 ("fs/ntfs3: Add attrib operations")
Signed-off-by: Konstantin Komarov <almaz.alexandrovich@paragon-software.com>

Here is the root cause:
The bug was caused by an incorrect calculation of the required space in clusters for storing attribute data when dealing with compressed files. The original logic did not account for the compression unit properly, leading to potential miscalculations in the transformation from resident to non-resident attributes.

Here is the patch:
  */
 int attr_make_nonresident(struct ntfs_inode *ni, struct ATTRIB *attr,
 			  struct ATTR_LIST_ENTRY *le, struct mft_inode *mi,
 			  u64 new_size, struct runs_tree *run,
 			  struct ATTRIB **ins_attr, struct page *page)
 {
 	struct ntfs_sb_info *sbi;
 	struct ATTRIB *attr_s;
 	struct MFT_REC *rec;
-	u32 used, asize, rsize, aoff, align;
+	u32 used, asize, rsize, aoff;
 	bool is_data;
 	CLST len, alen;
 	char *next;
 	int err;

 	if (attr->non_res) {
 		*ins_attr = attr;
 		return 0;
 	}

 	sbi = mi->sbi;
 	rec = mi->mrec;
 	attr_s = NULL;
 	used = le32_to_cpu(rec->used);
 	asize = le32_to_cpu(attr->size);
 	next = Add2Ptr(attr, asize);
 	aoff = PtrOffset(rec, attr);
 	rsize = le32_to_cpu(attr->res.data_size);
 	is_data = attr->type == ATTR_DATA && !attr->name_len;

-	align = sbi->cluster_size;
-	if (is_attr_compressed(attr))
-		align <<= NTFS_LZNT_CUNIT;
-	len = (rsize + align - 1) >> sbi->cluster_bits;
+	/* len - how many clusters required to store 'rsize' bytes */
+	if (is_attr_compressed(attr)) {
+		u8 shift = sbi->cluster_bits + NTFS_LZNT_CUNIT;
+		len = ((rsize + (1u << shift) - 1) >> shift) << NTFS_LZNT_CUNIT;
+	} else {
+		len = bytes_to_cluster(sbi, rsize);
+	}

 	run_init(run);

 	/* Make a copy of original attribute. */
 	attr_s = kmemdup(attr, asize, GFP_NOFS);
 	if (!attr_s) {
 		err = -ENOMEM;
 		goto out;
 	}

 	if (!len) {
 		/* Empty resident -> Empty nonresident. */
 		alen = 0;
 	} else {
 		const char *data = resident_data(attr);

 		err = attr_allocate_clusters(sbi, run, 0, 0, len, NULL,
 					     ALLOCATE_DEF, &alen, 0, NULL,
 					     NULL);
 		if (err)
 			goto out1;

 		if (!rsize) {
 			/* Empty resident -> Non empty nonresident. */
 		} else if (!is_data) {
 			err = ntfs_sb_write_run(sbi, run, 0, data, rsize, 0);
 			if (err)
 				goto out2;
 		} else if (!page) {
 			char *kaddr;

 			page = grab_cache_page(ni->vfs_inode.i_mapping, 0);
 			if (!page) {
 				err = -ENOMEM;
 				goto out2;
 			}
 			kaddr = kmap_atomic(page);
 			memcpy(kaddr, data, rsize);
 			memset(kaddr + rsize, 0, PAGE_SIZE - rsize);
 			kunmap_atomic(kaddr);
 			flush_dcache_page(page);
 			SetPageUptodate(page);
 			set_page_dirty(page);
 			unlock_page(page);
 			put_page(page);
 		}
 	}

 	/* Remove original attribute. */
 	used -= asize;
 	memmove(attr, Add2Ptr(attr, asize), used - aoff);
 	rec->used = cpu_to_le32(used);
 	mi->dirty = true;
 	if (le)
 		al_remove_le(ni, le);

 	err = ni_insert_nonresident(ni, attr_s->type, attr_name(attr_s),
 				    attr_s->name_len, run, 0, alen,
 				    attr_s->flags, &attr, NULL, NULL);
 	if (err)
 		goto out3;

 	kfree(attr_s);
 	attr->nres.data_size = cpu_to_le64(rsize);
 	attr->nres.valid_size = attr->nres.data_size;

 	*ins_attr = attr;

 	if (is_data)
 		ni->ni_flags &= ~NI_FLAG_RESIDENT;

 	/* Resident attribute becomes non resident. */
 	return 0;

 out3:
 	attr = Add2Ptr(rec, aoff);
 	memmove(next, attr, used - aoff);
 	memcpy(attr, attr_s, asize);
 	rec->used = cpu_to_le32(used + asize);
 	mi->dirty = true;
 out2:
 	/* Undo: do not trim new allocated clusters. */
 	run_deallocate(sbi, run, false);
 	run_close(run);
 out1:
 	kfree(attr_s);
 out:
 	return err;
 }



